const wh = $input.first().json;
const body = (wh.resume_id !== undefined) ? wh : (wh.body || wh);

const resumeId = body.resume_id;
const callbackUrl = body.callback_url;
const cvText = String(body.cv_text || '').slice(0, 6000);

if (!resumeId || !callbackUrl) {
  throw new Error('Dados em falta: resume_id=' + resumeId + ' callback_url=' + callbackUrl);
}

const prompt = 'Analisa o seguinte curriculo e responde APENAS com JSON valido com estes campos: score (0-100), skills (lista de strings), summary, experience, education, languages, feedback.\n\nCurriculo:\n' + cvText;

// Construir o body do pedido Ollama aqui garante que stream é boolean false (não string)
const ollamaBody = JSON.stringify({
  model: 'llama3.2:1b',
  stream: false,
  format: 'json',
  prompt: prompt
});

return [{ json: { resume_id: resumeId, callback_url: callbackUrl, prompt: prompt, ollama_body: ollamaBody } }];

const ollamaResp = $input.first().json;
const metadata = $('Construir Prompt CV').first().json;

function toStr(val) {
  if (val === null || val === undefined) return '';
  if (typeof val === 'string') return val.trim();
  if (Array.isArray(val)) return val.map(i => typeof i === 'object' ? JSON.stringify(i) : String(i)).join(', ');
  if (typeof val === 'object') return Object.values(val).filter(Boolean).join(' | ') || JSON.stringify(val);
  return String(val);
}

let analysis = {};
try {
  const raw = String(ollamaResp.response || ollamaResp.text || '{}');
  const cleaned = raw.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  analysis = JSON.parse(cleaned);
} catch(e) {
  analysis = {};
}

const score = Math.min(100, Math.max(0, parseFloat(analysis.score) || 50));
const skills = Array.isArray(analysis.skills) ? analysis.skills.map(s => typeof s === 'object' ? toStr(s) : String(s)).join(', ') : toStr(analysis.skills) || 'Nao identificadas';
const summary    = toStr(analysis.summary)    || 'Resumo nao disponivel';
const experience = toStr(analysis.experience) || 'Nao especificada';
const education  = toStr(analysis.education)  || 'Nao especificada';
const languages  = toStr(analysis.languages)  || 'Nao identificados';
const feedback   = toStr(analysis.feedback)   || 'Analise concluida.';

return [{
  json: {
    callback_url: metadata.callback_url,
    resume_id: metadata.resume_id,
    payload: JSON.stringify({ score, skills, summary, experience, education, languages, feedback })
  }
}];
